entries[107574] = { ["name"] = "Avatar", ["text"] = "Sofort 1.5 min Abklingzeit\nIhr verwandelt Euch für 20 Sek. in einen Koloss, wodurch Ihr 20 % mehr Schaden verursacht und Euch von allen bewegungseinschränkenden und Bewegungsunfähigkeitseffekten befreit.\n\nErzeugt ( 100 / 10) Wut." }
