entries[108273] = { ["name"] = "Totem des Windwandelns", ["text"] = "6% von Grundmana\nSofort 1 min Abklingzeit\nBeschwört ein Lufttotem mit (2 * Gesamtgesundheit / 100) Gesundheit zu Füßen des Zaubernden, das 6 Sek. lang bestehen bleibt und Schlachtzugsmitgliedern innerhalb von 40 Metern Immunität gegenüber bewegungseinschränkenden Effekten gewährt." }
