entries[108291] = { ["name"] = "Herz der Wildnis", ["text"] = "Sofort 5 min Abklingzeit\nFähigkeiten, die nicht zu Eurer Spezialisierung passen, sind für 45 Sek. erheblich verstärkt.\n\nWildheit, Wächter, Wiederherstellung\nGleichgewicht: Zauberzeit von Gleichgewichtzaubern sind um 30% verringert und Schaden ist um 20% erhöht\n\nGleichgewicht, Wächter, Wiederherstellung\nWildheit: Gewährt in Katzengestalt 1 Combopunkt alle 2 Sek. und körperlicher Schaden ist um 20% erhöht\n\nGleichgewicht, Wildheit, Wiederherstellung\nWächter: Die Bärengestalt verleiht Euch zusätzlich 20% Ausdauer, wiederholte Einsätze von 'Eisenfell' können sich überlappen und 'Rasende Regeneration' hat 2 Aufladungen\n\nGleichgewicht, Wildheit, Wächter\nWiederherstellung: Heilung ist um 30% erhöht und Manakosten sind um 50% verringert" }
