entries[108501] = { ["name"] = "Grimoire der Dienstbarkeit", ["text"] = "1.5 min Abklingzeit\nBeschwört einen zweiten Dämon, der Euch 25 Sek. lang im Kampf unterstützt und um 125% erhöhten Schaden verursacht. 1,5 Min. Abklingzeit. Der Dämon setzt nach der Beschwörung sofort eine seiner Spezialfähigkeiten ein:\n\nGrimoire: Wichtel : Entfernt 1 schädlichen Magieeffekt von Euch.\nGrimoire: Leerwandler : Verspottet das Ziel.\nGrimoire: Sukkubus : Verführt das Ziel.\nGrimoire: Teufelsjäger : Unterbricht das Ziel. [ Dämonologie : Grimoire: Teufelswache : Betäubt das Ziel ]" }
entries[108503] = { ["name"] = "Grimoire der Opferung", ["text"] = "Unbegrenzte Reichweite\nSofort 30 sek. Abklingzeit\nOpfert Euren Dämonenbegleiter, um Macht zu gewinnen. Gewährt Euch seine Fähigkeit von 'Dämon kommandieren' und lässt Eure Zauber manchmal zusätzlich (37.1875% der Zaubermacht) Schattenschaden verursachen.\n\nHält bis Abbruch lang an oder bis Ihr einen Dämonenbegleiter beschwört." }
